CATS=["Matemáticas","Historia","Inglés","Arte y Cultura","Lengua castellana","Física","Tecnología","Filosofía"]
TUT=[("Matemáticas","Prof. Andrea Ruiz","$40"),("Inglés","Prof. Daniel Cruz","$35"),("Historia","Prof. Laura Mena","$30"),("Programación","Prof. Camilo Pardo","$45"),("Física","Prof. Sergio Vélez","$40")]
MAS=[("Contabilidad","$40"),("Economía","$40"),("Emprendimiento","$40"),("Ecuaciones diferenciales","$40"),("Cálculo integral","$40"),("Marketing digital","$40")]
def head(sesion):
    acc='<a href="perfil.html">Perfil</a><a href="carrito.html">Carrito</a>' if sesion else '<a href="login.html">Iniciar sesión</a>'
    cats="".join(f'<a href="biblioteca.html">{c}</a>' for c in ["Nuevo"]+CATS)
    return f'<header class="top"><div class="bar"><a class="logo" href="index.html">TutoresOn-Line</a><div class="buscar">Buscar tutor o materia</div><nav class="mini"><a href="comunidad.html">Comunidad</a>{acc}</nav></div></header><div class="cats">{cats}</div>'
FOOT='<footer><div><p>Síguenos en YouTube · Facebook · Instagram · X</p><p>© TutoresOn-Line. Todos los derechos reservados.</p></div><nav><a href="#">Privacidad y términos</a><a href="#">Cookies</a><a href="#">CCPA</a><a href="#">Principios de IA</a></nav><strong>TutoresOn-Line</strong></footer>'
def page(name,title,body,sesion=True):
    open(name,"w",encoding="utf-8").write(f'<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · TutoresOn-Line</title><link rel="stylesheet" href="css/style.css"></head><body>{head(sesion)}<main>{body}</main>{FOOT}</body></html>')
def fila(): return '<div class="fila">'+"".join(f'<div class="tutoria"><b>{m}</b><small>{t}</small><a class="btn" href="carrito.html">Reservar {p}/h</a></div>' for m,t,p in TUT)+'</div>'
def zona(t): return f'<h2>{t}</h2>{fila()}'
home=lambda: '<section class="hero"><div><h1>Aprender es descubrir.<br>Descubrir es TutoresOn-Line</h1><p>Pausa el mundo y empieza a aprender. Encuentra al tutor ideal para cada materia y agenda tu sesión en minutos.</p></div><div class="img"></div></section>'+zona("Top 10 tutorías")+zona("Clásicas")+zona("Más reservadas")+'<h2>Te puede interesar</h2><div class="grid">'+"".join(f'<a class="item" href="carrito.html"><div class="mini"></div><div><b>{n}</b><br>{p}/h<br><small>4.7 ★★★★★ (835)</small></div></a>' for n,p in MAS)+'</div><div class="centro"><a class="btn" href="biblioteca.html">VER MÁS</a></div>'
page("index.html","Inicio",home(),False)
page("home-sesion.html","Inicio",home(),True)
