page("registro.html","Registro",'<div class="caja"><h1 style="text-align:center">Crea tu cuenta</h1><label>NOMBRE COMPLETO</label><input placeholder="Nombre y apellido"><label>CORREO ELECTRÓNICO</label><input type="email" placeholder="nombre@ejemplo.com"><label>CONTRASEÑA</label><input type="password"><label>SOY</label><input placeholder="Estudiante o tutor"><p style="text-align:center;margin-top:24px"><a class="btn azul" href="home-sesion.html">Registrarme</a></p><p style="text-align:center">¿Ya tienes cuenta? <a href="login.html"><b>Inicia sesión</b></a></p></div>',False)
page("perfil.html","Mi perfil",'<div class="perfil"><div class="tarjeta"><div class="avatar"></div><h2>John Doe</h2><p>johndoe@gmail.com</p><p>Nivel 11 · 1230 / 1500 puntos</p><div class="barra"><i></i></div></div><div class="menu"><a href="biblioteca.html">Mis tutorías</a><a href="metodos-pago.html">Métodos de pago</a><a href="#">Centro de ayuda</a><a href="index.html">Cerrar sesión</a></div></div>')
page("metodos-pago.html","Métodos de pago",'<h1>Métodos de pago</h1>'+"".join(f'<div class="linea"><div><b>{n}</b><br><small>Vence 12/2028</small><br><a href="#">Editar</a> · <a href="#">Eliminar</a></div></div>' for n in ["Visa terminada en 4417","Mastercard terminada en 9021","PSE"])+'<a class="btn azul" href="#">Agregar método de pago</a>')
