page("biblioteca.html","Mis tutorías",'<h1>Mis tutorías</h1><div class="grid">'+"".join(f'<div class="linea"><div class="mini"></div><div><b>{n}</b><br>{p}/h<br><small>4.7 ★★★★★ (835)</small><br><br><a class="btn" href="comunidad.html">Ver sesión</a></div></div>' for n,p in MAS[:4])+'</div><h2>También te puede interesar</h2>'+fila())
